#include "dfre/mission_df_join.hpp"
#include <array>
#include <iostream>
#include <sstream>
#include <stdexcept>
namespace {using U=std::uint32_t;struct Test{std::array<U,24>row{};std::array<std::uint8_t,0x100>cells{};std::array<std::uint8_t,0x400>data{};std::array<std::uint8_t,16>constant{};std::array<std::uint8_t,0x118>frame{};U reads=0,writes=0,calls=0;std::uint64_t trace=1469598103934665603ull;std::uint8_t*ptr(U a,U n){if(a>=0x501300&&std::uint64_t(a-0x501300)+n<=cells.size())return cells.data()+a-0x501300;if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=data.size())return data.data()+a-0x1200000;if(a>=0x4cebc4&&std::uint64_t(a-0x4cebc4)+n<=constant.size())return constant.data()+a-0x4cebc4;if(a>=0x3000000&&std::uint64_t(a-0x3000000)+n<=frame.size())return frame.data()+a-0x3000000;throw std::runtime_error("DF Join fixture address is not mapped");}U get(U a,U n=4){auto*p=ptr(a,n);U v=0;for(U i=0;i<n;++i)v|=U(p[i])<<(8*i);return v;}void put(U a,U v,U n=4){auto*p=ptr(a,n);for(U i=0;i<n;++i)p[i]=std::uint8_t(v>>(8*i));}U norm(U a){return a>=0x3000000&&a<0x3000118?0x30000000+a-0x3000000:a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}U selected(){return row[2]==0?0:row[2]==2?0x3000070:row[2]==3?0x1200100:row[2]==4?0x30000bc:0x1200000;}U password(){return row[3]==0?0:row[3]==2?0x3000040:row[3]==3?0x3000090:0x1200200;}
void setup(){cells.fill(0x5a);data.fill(0x5a);frame.fill(0x5a);put(0x501320,row[1]);put(0x4cebc4,row[7]);put(0x4cebc8,0x11d16b35);put(0x4cebcc,0xc0008787);put(0x4cebd0,0x25af16f0);put(0x1200010,row[8]);put(0x1200110,row[8]+1);for(U i=1;i<4;++i){put(0x1200010+i*4,0x11223344u*(i+1));put(0x1200110+i*4,0x22334455u*(i+1));}for(U i=0;i<0x100;++i)put(0x1200200+i,'a'+i%26,1);if(row[4]<0x100)put(0x1200200+row[4],0,1);put(0x3000110,selected());put(0x3000114,password());}
dfre::MissionGameTransportBindings bindings(){dfre::MissionGameTransportBindings b;b.read=[&](U a,U n){event(1);event(norm(a));event(n);if(++reads==row[10])throw std::runtime_error("Read failure");if((row[9]&32)&&a==0x4cebc4)put(0x3000114,0);return get(a,n);};b.write=[&](U a,U n,U v){event(2);event(norm(a));event(n);event(norm(n==4?v:v&255));if(++writes==row[11]||(a>=0x3000100&&a<0x3000110))throw std::runtime_error("Store failure");if((row[9]&256)&&a==0x30000d0&&selected())put(selected()+0x14,0x98765432);if((row[9]&512)&&a==0x30000e0)put(0x4cebc8,0x87654321);if((row[9]&8)&&a==0x30000d0)put(0x4cebc4,0xabcdef01);if((row[9]&16)&&a==0x30000e0)put(0x1200200,'z',1);put(a,v,n);};b.before_call=[&](U s,const auto&args){event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[12])throw std::runtime_error("Call failure");};b.call=[&](U s,const auto&args)->U{if(s==0x4c5544){if(row[9]&1){put(0x3000110,0x1200100);put(0x3000114,0);}if(row[9]&2){if(selected())put(selected()+0x10,0xdeadbeef);put(0x1200200,'x',1);}if(row[9]&128)put(0x501320,0);return row[5];}if(s==0x49a620){for(U i=0;i<args.at(2);++i){if(row[13]&&i==row[13])throw std::runtime_error("Memset prefix failure");put(args.at(0)+i,args.at(1)&255,1);}if(row[9]&4){put(0x4cebc4,0xface1234);if(selected())put(selected()+0x10,0xbeef5678);}return args[0];}if(s==0x4c553e){if(row[9]&64)put(0x501368,1);return row[6];}throw std::runtime_error("DF Join required service is not bound");};return b;}
};}
int main(){std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;Test t;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();bool failed=false;U result=0;try{auto b=t.bindings();result=t.row[0]?dfre::mission_df_join_stop_enum(b):dfre::mission_df_join(b,0x3000000);}catch(const std::runtime_error&){failed=true;}if(failed)result=0;std::uint64_t state=1469598103934665603ull;const auto hash=[&](const auto&bytes){for(auto v:bytes){state^=v;state*=1099511628211ull;}};hash(t.cells);hash(t.data);hash(t.constant);for(U i=0;i<0x100;++i){state^=t.frame[i];state*=1099511628211ull;}std::cout<<failed<<' '<<result<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
